// Validates every theme in themes/ and generates src/theme-registry.generated.ts,
// which the app imports. The generated file holds static require() calls so
// the bundler picks up each theme's images and sounds.
//
// Run with: npm run themes   (also runs automatically before `npm start`
// and whenever the Theme Studio saves)

import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { join } from 'node:path';

import { THEMES_DIR, validateTheme } from './schema.mjs';

const themesDir = fileURLToPath(THEMES_DIR);
const outFile = fileURLToPath(new URL('../../src/theme-registry.generated.ts', import.meta.url));

export function loadThemes() {
  const themes = [];
  const errors = [];
  const warnings = [];
  for (const id of readdirSync(themesDir, { withFileTypes: true }).filter((d) => d.isDirectory() && !d.name.startsWith('.')).map((d) => d.name)) {
    const dir = join(themesDir, id);
    const file = join(dir, 'theme.json');
    if (!existsSync(file)) {
      warnings.push(`${id}: no theme.json, skipped`);
      continue;
    }
    let json;
    try {
      json = JSON.parse(readFileSync(file, 'utf8'));
    } catch (e) {
      errors.push(`${id}: theme.json is not valid JSON (${e.message})`);
      continue;
    }
    const result = validateTheme(id, json, dir);
    errors.push(...result.errors);
    warnings.push(...result.warnings);
    if (result.errors.length === 0) themes.push({ id, ...json });
  }
  themes.sort((a, b) => a.order - b.order || a.name.localeCompare(b.name));
  return { themes, errors, warnings };
}

// require() calls are written as placeholders, then unquoted after JSON.stringify.
const req = (id, file) => `@@require('../themes/${id}/${file}')@@`;

function toData(t) {
  const { background, particles, sounds, ...meta } = t;
  return {
    ...meta,
    backgroundImage: background.image ? req(t.id, background.image) : null,
    backgroundDim: background.dim,
    particleStyle: particles.style,
    particleColors: particles.colors,
    particleImages: particles.images.map((f) => req(t.id, f)),
    particleAmount: particles.amount,
    particleOpacity: particles.opacity,
    sounds: Object.fromEntries(
      Object.entries(sounds ?? {}).map(([slot, s]) => [
        slot,
        { sources: s.files.slice(0, slot === 'tap' ? 3 : 1).map((f) => req(t.id, f)), volume: s.volume },
      ]),
    ),
  };
}

function render(themes) {
  const body = JSON.stringify(themes.map(toData), null, 2).replace(/"@@(.*?)@@"/g, '$1');
  return `// GENERATED by scripts/themes/build.mjs from the themes/ folder. Do not edit:
// change themes with the Theme Studio (npm run studio) or edit themes/*/theme.json.

import type { ThemeData } from './theme';

export const THEME_DATA: ThemeData[] = ${body};
`;
}

export function buildThemes({ quiet = false } = {}) {
  // Themes with errors are left out; the rest still build, so one
  // half-finished theme never breaks the app.
  const { themes, errors, warnings } = loadThemes();
  const next = render(themes);
  const prev = existsSync(outFile) ? readFileSync(outFile, 'utf8') : '';
  // Only touch the file when it changes, so Metro doesn't reload for nothing.
  if (next !== prev) writeFileSync(outFile, next);
  if (!quiet) {
    for (const w of warnings) console.warn(`  ⚠ ${w}`);
    for (const e of errors) console.error(`  ✖ ${e}`);
    console.log(`Built ${themes.length} themes${errors.length ? ` (themes with errors were left out)` : ''}.`);
  }
  return { themes, errors, warnings };
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const { errors } = buildThemes();
  process.exitCode = errors.length ? 1 : 0;
}
